<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Book catalog</h2><p class="text-muted">Searchable collection and inventory availability.</p></div><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=books&action=create">+ Add book</a></div><div class="card p-3"><input class="form-control mb-3" id="bookSearch" placeholder="Search title, author, ISBN, or category"><div class="table-responsive"><table class="table align-middle" id="bookTable"><thead><tr><th>ISBN</th><th>Title</th><th>Author</th><th>Category</th><th>Classification</th><th>Available</th><th>Condition</th><th>Action</th></tr></thead><tbody><?php foreach($books as $b):?><tr><td><?= Security::e($b['isbn']) ?></td><td class="fw-semibold"><?= Security::e($b['title']) ?></td><td><?= Security::e($b['author']) ?></td><td><?= Security::e($b['category']??'Unclassified') ?></td><td><?= Security::e($b['classification']??'—') ?></td><td><?= (int)$b['available_quantity'] ?> / <?= (int)$b['quantity'] ?></td><td><span class="badge badge-soft"><?= Security::e(ucfirst($b['condition_status'])) ?></span></td><td><form method="post" action="<?= BASE_URL ?>/?page=books&action=delete" onsubmit="return confirm('Delete this book?');"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $b['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><script>document.getElementById('bookSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#bookTable tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q));});</script><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
